CREATE TABLE entities (entity_id TEXT PRIMARY KEY, entity_type TEXT NOT NULL);
CREATE TABLE "licenses" ("license" TEXT,"license_id" TEXT PRIMARY KEY,"commercial_use" TEXT,"redistribution_allowed" TEXT,"derivative_allowed" TEXT,"attribution_required" INTEGER,"raw_data_allowed" TEXT,"rights_status" TEXT,"rights_scope" TEXT,"terms_url" TEXT,"evidence_urls" TEXT,"reviewed_at" TEXT,"notes" TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE "sources" ("source_id" TEXT PRIMARY KEY,"source_name" TEXT,"url" TEXT,"license_id" TEXT,"revisions" TEXT,"collected_at" TEXT,"storage_policy" TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)),FOREIGN KEY("license_id") REFERENCES "licenses"("license_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "factor_concepts" ("canonical_factor_id" TEXT PRIMARY KEY,"canonical_name" TEXT,"short_id" TEXT,"aliases" TEXT,"description" TEXT,"economic_logic" TEXT,"category" TEXT,"scope" TEXT,"created_at" TEXT,"updated_at" TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE "authors" ("author_id" TEXT PRIMARY KEY,"name" TEXT,"identity_status" TEXT,"namespace" TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE "papers" ("paper_id" TEXT PRIMARY KEY,"title" TEXT,"year" INTEGER,"authors" TEXT,"author_ids" TEXT,"url" TEXT,"citation_label" TEXT,"metadata_status" TEXT,"provenance" TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE "formulas" ("formula_id" TEXT PRIMARY KEY,"raw_formula" TEXT,"normalized_formula" TEXT,"formula_ast" TEXT,"dialect" TEXT,"semantic_status" TEXT,"source_record_ids" TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE "datasets" ("dataset_id" TEXT PRIMARY KEY,"name" TEXT,"source_id" TEXT,"content_type" TEXT,"revision" TEXT,"license_id" TEXT,"source_url" TEXT,"observations_ingested" INTEGER,payload TEXT NOT NULL CHECK(json_valid(payload)),FOREIGN KEY("source_id") REFERENCES "sources"("source_id") DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY("license_id") REFERENCES "licenses"("license_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "factor_variants" ("license" TEXT,"license_id" TEXT,"commercial_use" TEXT,"redistribution_allowed" TEXT,"derivative_allowed" TEXT,"attribution_required" INTEGER,"raw_data_allowed" TEXT,"rights_status" TEXT,"rights_scope" TEXT,"terms_url" TEXT,"canonical_factor_id" TEXT,"canonical_name" TEXT,"factor_concept" TEXT,"factor_variant_id" TEXT PRIMARY KEY,"variant_name" TEXT,"aliases" TEXT,"description" TEXT,"economic_logic" TEXT,"category" TEXT,"raw_formula" TEXT,"normalized_formula" TEXT,"formula_ast" TEXT,"formula_id" TEXT,"dialect" TEXT,"parameters" TEXT,"required_fields" TEXT,"required_fields_status" TEXT,"lookback" TEXT,"frequency" TEXT,"asset_class" TEXT,"universe" TEXT,"holding_period" TEXT,"rebalance" TEXT,"source_id" TEXT,"source_name" TEXT,"source_url" TEXT,"source_record_ids" TEXT,"source_native_ids" TEXT,"source_sha256" TEXT,"source_revision" TEXT,"source_locator" TEXT,"paper_title" TEXT,"paper_year" INTEGER,"authors" TEXT,"paper_ids" TEXT,"code_url" TEXT,"quality_status" TEXT,"semantic_status" TEXT,"backtest_ready" INTEGER,"issue_codes" TEXT,"created_at" TEXT,"updated_at" TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)),FOREIGN KEY("canonical_factor_id") REFERENCES "factor_concepts"("canonical_factor_id") DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY("source_id") REFERENCES "sources"("source_id") DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY("license_id") REFERENCES "licenses"("license_id") DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY("formula_id") REFERENCES "formulas"("formula_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "source_records" ("record_id" TEXT PRIMARY KEY,"factor_variant_id" TEXT,"source_id" TEXT,"source_native_id" TEXT,"source_url" TEXT,"source_locator" TEXT,"sha256" TEXT,"dataset_id" TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)),FOREIGN KEY("factor_variant_id") REFERENCES "factor_variants"("factor_variant_id") DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY("source_id") REFERENCES "sources"("source_id") DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY("dataset_id") REFERENCES "datasets"("dataset_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "implementations" ("implementation_id" TEXT PRIMARY KEY,"factor_variant_id" TEXT,"source_record_id" TEXT,"code_url" TEXT,"revision" TEXT,"sha256" TEXT,"source_locator" TEXT,"language" TEXT,"status" TEXT,"license" TEXT,"terms_url" TEXT,"commercial_use" TEXT,"executed" INTEGER,payload TEXT NOT NULL CHECK(json_valid(payload)),FOREIGN KEY("factor_variant_id") REFERENCES "factor_variants"("factor_variant_id") DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY("source_record_id") REFERENCES "source_records"("record_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "strategies" ("strategy_id" TEXT PRIMARY KEY,"canonical_name" TEXT,"aliases" TEXT,"description" TEXT,"entry_rules" TEXT,"exit_rules" TEXT,"position_sizing" TEXT,"risk_management" TEXT,"asset_class" TEXT,"universe" TEXT,"frequency" TEXT,"rebalance" TEXT,"factor_ids" TEXT,"source" TEXT,"paper" TEXT,"code" TEXT,"original_backtest" TEXT,"reproduced_backtest" TEXT,"external_namespace" TEXT,"external_id" TEXT,"spec_sha256" TEXT,"status" TEXT,"created_at" TEXT,"updated_at" TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)));
CREATE TABLE "backtest_results" ("backtest_result_id" TEXT PRIMARY KEY,"strategy_id" TEXT,"result_kind" TEXT,"research_project" TEXT,"artifact_uri" TEXT,"artifact_sha256" TEXT,"contract_uri" TEXT,"metrics" TEXT,"validation_status" TEXT,"created_at" TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)),FOREIGN KEY("strategy_id") REFERENCES "strategies"("strategy_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "strategy_factor" ("strategy_id" TEXT,"factor_id" TEXT,"variant_id" TEXT,"role" TEXT,"confidence" REAL,"evidence" TEXT,"source" TEXT,"attribution_status" TEXT,"backtest_result_id" TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)),PRIMARY KEY(strategy_id,variant_id,role),CHECK(confidence >= 0 AND confidence <= 1),CHECK(role IN ('signal','entry','exit','filter','weight','risk','exposure')),CHECK(length(evidence)>0 AND length(source)>0),CHECK(attribution_status != 'EMPIRICALLY_TESTED' OR backtest_result_id IS NOT NULL),FOREIGN KEY("strategy_id") REFERENCES "strategies"("strategy_id") DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY("variant_id") REFERENCES "factor_variants"("factor_variant_id") DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY("factor_id") REFERENCES "factor_concepts"("canonical_factor_id") DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY("backtest_result_id") REFERENCES "backtest_results"("backtest_result_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "aliases" ("alias_id" TEXT PRIMARY KEY,"alias" TEXT,"normalized_alias" TEXT,"namespace" TEXT,"factor_variant_id" TEXT,"canonical_factor_id" TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)),FOREIGN KEY("factor_variant_id") REFERENCES "factor_variants"("factor_variant_id") DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY("canonical_factor_id") REFERENCES "factor_concepts"("canonical_factor_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "id_map" ("legacy_record_id" TEXT PRIMARY KEY,"legacy_canonical_factor_id" TEXT,"canonical_factor_id" TEXT,"factor_variant_id" TEXT,"short_id" TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)),FOREIGN KEY("factor_variant_id") REFERENCES "factor_variants"("factor_variant_id") DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY("canonical_factor_id") REFERENCES "factor_concepts"("canonical_factor_id") DEFERRABLE INITIALLY DEFERRED);
CREATE TABLE "relationships" ("relationship_id" TEXT PRIMARY KEY,"relation" TEXT,"from_id" TEXT,"from_type" TEXT,"to_id" TEXT,"to_type" TEXT,"confidence" REAL,"evidence" TEXT,"source" TEXT,"status" TEXT,payload TEXT NOT NULL CHECK(json_valid(payload)),FOREIGN KEY("from_id") REFERENCES "entities"("entity_id") DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY("to_id") REFERENCES "entities"("entity_id") DEFERRABLE INITIALLY DEFERRED);
CREATE INDEX idx_variant_concept ON factor_variants(canonical_factor_id);
CREATE INDEX idx_variant_category ON factor_variants(category,asset_class);
CREATE INDEX idx_alias_name ON aliases(normalized_alias,namespace);
CREATE INDEX idx_relation_from ON relationships(from_id);
CREATE INDEX idx_relation_to ON relationships(to_id);
CREATE INDEX idx_sf_factor ON strategy_factor(factor_id,variant_id);
CREATE TRIGGER strategy_factor_concept_insert BEFORE INSERT ON strategy_factor
    WHEN NEW.factor_id != (SELECT canonical_factor_id FROM factor_variants WHERE factor_variant_id=NEW.variant_id)
    BEGIN SELECT RAISE(ABORT,'variant does not belong to factor concept'); END;
CREATE TRIGGER strategy_factor_concept_update BEFORE UPDATE ON strategy_factor
    WHEN NEW.factor_id != (SELECT canonical_factor_id FROM factor_variants WHERE factor_variant_id=NEW.variant_id)
    BEGIN SELECT RAISE(ABORT,'variant does not belong to factor concept'); END;
